void updatePhysics(const std::vector<CelestialBody>& bodies, std::vector<Spacecraft>& spacecrafts, float deltaTime) {
    // Reset forces
    for (auto& s : spacecrafts) {
        s.force = {0.f, 0.f, 0.f};
    }
    for (auto& b : bodies) {
        b.force = {0.f, 0.f, 0.f};
    }

    // Calculate gravitational forces between bodies and spacecraft
    for (auto& c : spacecrafts) {
        for (auto& b : bodies) {
            Vector3 forceOnCraft;
            Vector3 forceOnBody;
            calculateGravitationalForce(c, b, forceOnCraft, forceOnBody);

            c.force += forceOnCraft;
            b.force += forceOnBody;
        }
    }

    // Update velocities
    for (auto& s : spacecrafts) {
        s.velocity += s.force * deltaTime / s.mass;
    }
    for (auto& b : bodies) {
        b.velocity += b.force * deltaTime / b.mass;
    }

    // Update positions
    for (auto& s : spacecrafts) {
        s.position += s.velocity * deltaTime;
    }
    for (auto& b : bodies) {
        b.position += b.velocity * deltaTime;
    }
}
```

